import { describe, expect, it } from "vitest";

import {
  CANONICAL_ORIGIN,
  SITEMAP_EXCLUDED_BLOG_SLUGS,
  isExcludedBlogSlug,
  sitemapLastmod,
  toCanonicalUrl,
} from "../seo-canonical";

describe("toCanonicalUrl", () => {
  it("rewrites www.authhub.co to the non-www origin", () => {
    expect(toCanonicalUrl("https://www.authhub.co/guides/meta-ads-access")).toBe(
      `${CANONICAL_ORIGIN}/guides/meta-ads-access`
    );
  });

  it("leaves already-canonical authhub.co URLs unchanged", () => {
    expect(toCanonicalUrl(`${CANONICAL_ORIGIN}/blog/snapchat-ads-access-agencies`)).toBe(
      `${CANONICAL_ORIGIN}/blog/snapchat-ads-access-agencies`
    );
  });
});

describe("sitemap exclusions", () => {
  it("excludes blog slugs that 301 to a canonical page", () => {
    expect(SITEMAP_EXCLUDED_BLOG_SLUGS).toEqual([
      "how-to-get-meta-ads-access-from-clients",
      "leadsie-vs-authhub-comparison",
    ]);
    expect(isExcludedBlogSlug("how-to-get-meta-ads-access-from-clients")).toBe(true);
    expect(isExcludedBlogSlug("google-ads-access-agency")).toBe(false);
  });
});

describe("sitemapLastmod", () => {
  it("prefers the first parseable candidate so updatedAt wins over publishedAt", () => {
    expect(sitemapLastmod("2026-10-06", "2026-09-11")).toBe(
      new Date("2026-10-06").toISOString()
    );
  });

  it("falls through to publishedAt when updatedAt is missing", () => {
    expect(sitemapLastmod(undefined, "2026-01-15")).toBe(
      new Date("2026-01-15").toISOString()
    );
  });
});

import { describe, expect, it } from "vitest";

import sitemap from "@/app/sitemap";
import { getBlogPostBySlug } from "@/lib/blog-data";
import { getComparisonLastVerified } from "@/lib/comparison-data";
import { SITEMAP_EXCLUDED_BLOG_SLUGS } from "@/lib/seo-canonical";

function pathnames(): string[] {
  return sitemap().map((entry) => new URL(entry.url).pathname);
}

describe("sitemap indexation", () => {
  it("omits blog slugs that 301 to a canonical page", () => {
    const paths = pathnames();
    for (const slug of SITEMAP_EXCLUDED_BLOG_SLUGS) {
      expect(paths).not.toContain(`/blog/${slug}`);
    }
  });

  it("keeps the canonical destinations for those redirects", () => {
    const paths = pathnames();
    expect(paths).toContain("/guides/meta-ads-access");
    expect(paths).toContain("/compare/leadsie-vs-agencyaccess-vs-authhub");
  });

  it("uses updatedAt for lastmod when a post has been refreshed", () => {
    const snapchat = getBlogPostBySlug("snapchat-ads-access-agencies");
    expect(snapchat?.updatedAt).toBe("2026-10-06");

    const entry = sitemap().find(
      (item) => new URL(item.url).pathname === "/blog/snapchat-ads-access-agencies"
    );
    expect(entry?.lastModified).toBe(new Date("2026-10-06").toISOString());
  });

  it("uses lastVerified for compare page lastmod", () => {
    const verified = getComparisonLastVerified("clientinvite-alternative");
    expect(verified).toBe("2026-10-01");

    const entry = sitemap().find(
      (item) => new URL(item.url).pathname === "/compare/clientinvite-alternative"
    );
    expect(entry?.lastModified).toBe(new Date("2026-10-01").toISOString());
  });
});

import { describe, expect, it } from "vitest";

import robots from "@/app/robots";
import { AI_SEARCH_USER_AGENTS } from "@/lib/seo-canonical";

describe("robots.txt", () => {
  it("allows named AI search crawlers", () => {
    const config = robots();
    const rules = Array.isArray(config.rules) ? config.rules : [config.rules];
    const allowedAgents = rules.flatMap((rule) => {
      if (!rule || rule.allow === undefined) return [];
      const agents = Array.isArray(rule.userAgent) ? rule.userAgent : [rule.userAgent];
      const allows = Array.isArray(rule.allow) ? rule.allow : [rule.allow];
      return allows.includes("/") ? agents : [];
    });

    for (const agent of AI_SEARCH_USER_AGENTS) {
      expect(allowedAgents).toContain(agent);
    }
  });

  it("still disallows authenticated surfaces for the wildcard crawler", () => {
    const config = robots();
    const rules = Array.isArray(config.rules) ? config.rules : [config.rules];
    const wildcard = rules.find((rule) => rule.userAgent === "*");
    expect(wildcard?.disallow).toEqual(["/api/", "/admin/", "/agency/"]);
  });
});

import { describe, expect, it } from "vitest";

import { webSiteSchema } from "../root-schemas";

describe("webSiteSchema", () => {
  it("does not advertise a SearchAction for a /search route that does not exist", () => {
    expect(JSON.stringify(webSiteSchema)).not.toContain("SearchAction");
    expect(JSON.stringify(webSiteSchema)).not.toContain("/search");
  });

  it("identifies the AuthHub site on the canonical origin", () => {
    expect(webSiteSchema["@type"]).toBe("WebSite");
    expect(webSiteSchema.url).toBe("https://authhub.co");
  });
});

import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

const LLMS_PATH = path.join(process.cwd(), "public", "llms.txt");

describe("llms.txt", () => {
  it("exists at the site root and lists money pages", () => {
    expect(existsSync(LLMS_PATH)).toBe(true);
    const body = readFileSync(LLMS_PATH, "utf-8");
    expect(body).toContain("https://authhub.co/pricing");
    expect(body).toContain("https://authhub.co/guides/meta-ads-access");
    expect(body).toContain("https://authhub.co/guides/google-ads-access");
    expect(body).toContain("https://authhub.co/compare/clientinvite-alternative");
    expect(body).toContain("https://authhub.co/compare/leadsie-alternative");
    expect(body).toContain("https://docs.authhub.co");
  });
});

export const CANONICAL_ORIGIN = "https://authhub.co";

export const SITEMAP_EXCLUDED_BLOG_SLUGS = [
  "how-to-get-meta-ads-access-from-clients",
  "leadsie-vs-authhub-comparison",
] as const;

export const AI_SEARCH_USER_AGENTS = [
  "GPTBot",
  "ChatGPT-User",
  "PerplexityBot",
  "ClaudeBot",
  "Google-Extended",
] as const;

export function toCanonicalUrl(url: string): string {
  return url.replace(/^https?:\/\/www\.authhub\.co/i, CANONICAL_ORIGIN);
}

export function isExcludedBlogSlug(slug: string): boolean {
  return (SITEMAP_EXCLUDED_BLOG_SLUGS as readonly string[]).includes(slug);
}

export function sitemapLastmod(
  ...candidates: Array<string | undefined>
): string | undefined {
  for (const candidate of candidates) {
    if (!candidate) continue;
    const date = new Date(candidate);
    if (!Number.isNaN(date.getTime())) {
      return date.toISOString();
    }
  }
  return undefined;
}

export const organizationSchema = {
  "@context": "https://schema.org",
  "@type": "Organization",
  name: "AuthHub",
  url: "https://authhub.co",
  logo: "https://authhub.co/authhub.png",
  description:
    "Client access platform for marketing agencies. Replace weeks of OAuth setup with a single 5-minute link.",
  sameAs: [
    "https://twitter.com/authhubco",
    "https://linkedin.com/company/authhub-platform",
  ],
  contactPoint: {
    "@type": "ContactPoint",
    contactType: "customer support",
    url: "https://authhub.co/contact",
  },
};

export const webSiteSchema = {
  "@context": "https://schema.org",
  "@type": "WebSite",
  name: "AuthHub",
  url: "https://authhub.co",
  description: "Client access platform for marketing agencies",
};

